<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$user=(string)$_SESSION['name'];$a=$user.';%';$b='%;'.$user.';%';$c='%;'.$user;$s=tt_prepare($db,"SELECT `id`,`title`,`content`,`dt`,`tags`,`name`,`recipients`,`file`,`comments`,`scope`,`type` FROM `posts` WHERE `type`='message' AND (`name`=? OR `recipients`=? OR `recipients` LIKE ? OR `recipients` LIKE ? OR `recipients` LIKE ?) ORDER BY `dt` DESC,`id` DESC LIMIT 150");$s->bind_param('sssss',$user,$user,$a,$b,$c);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Messages</title></head><body><?php tt_nav('messages.php');?><main class="content"><div class="actions"><a href="create.php?mode=message">New message</a></div><h2>Messages</h2><section class="grid"><?php foreach($rows as $r):$targetUser=tt_reply_target_user((string)$r['name'],(string)$r['recipients'],$user);?><article class="card post-card" id="post-<?=(int)$r['id']?>" data-post-expandable="1" aria-expanded="false"><h3><?=tt_h($r['title'])?></h3><p class="meta">#<?=(int)$r['id']?> · From <?=tt_h($r['name'])?> · to <?=tt_h($r['recipients'])?> · <?=tt_h($r['dt'])?></p><p><?=nl2br(tt_h($r['content']))?></p><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>">Attachment</a></p><?php endif;?><?php if(trim((string)$r['comments'])!==''):?><details class="comments-disclosure"><summary>Comments</summary><pre class="comments-body"><?=tt_h($r['comments'])?></pre></details><?php endif;?><div class="actions"><a href="<?=tt_h(tt_compose_url('comment',(int)$r['id'],(string)$r['name'],'message',(string)$r['title'],trim((string)$r['scope']),$targetUser))?>">Comment</a><a href="<?=tt_h(tt_compose_url('reply',(int)$r['id'],(string)$r['name'],'message',(string)$r['title'],trim((string)$r['scope']),$targetUser))?>">Reply as message</a></div></article><?php endforeach;?><?php if(!$rows):?><article class="card"><p>No messages yet.</p></article><?php endif;?></section></main></body></html>